"use client";

import { ActionForm } from "@/components/shared/action-form";
import { SubmitButton } from "@/components/shared/submit-button";
import { purchaseItemAction } from "@/features/adventures/actions";

/**
 * `idempotencyKey` is generated by the server for each render of the page, so a double click or a
 * retried request charges once; after a successful purchase the page re-renders with fresh keys.
 */
export function PurchaseButton({
  itemKey,
  itemName,
  costCoins,
  idempotencyKey,
  disabled,
}: {
  itemKey: string;
  itemName: string;
  costCoins: number;
  idempotencyKey: string;
  disabled: boolean;
}) {
  return (
    <ActionForm
      action={purchaseItemAction}
      successMessage={`You bought ${itemName}!`}
      resetOnSuccess={false}
      className="space-y-1"
    >
      <input type="hidden" name="itemKey" value={itemKey} />
      <input type="hidden" name="idempotencyKey" value={idempotencyKey} />
      <SubmitButton
        className="min-h-12 rounded-2xl px-5 text-base font-black"
        disabled={disabled}
        pendingText="Buying…"
        aria-label={`Buy ${itemName} for ${costCoins} coins`}
        data-testid={`buy-${itemKey}`}
      >
        Buy · 🪙 {costCoins}
      </SubmitButton>
    </ActionForm>
  );
}
